UPDATE community_post p
SET p.like_count = (SELECT COUNT(*) FROM community_post_like l WHERE l.post_id = p.id)
WHERE p.id = #{postId}

UPDATE community_post p
SET p.favorite_count = (SELECT COUNT(*) FROM community_post_favorite f WHERE f.post_id = p.id)
WHERE p.id = #{postId}

UPDATE community_post p
SET p.comment_count = (
    SELECT COUNT(*) FROM community_comment c WHERE c.post_id = p.id AND c.status = 'PUBLISHED'
)
WHERE p.id = #{postId}

UPDATE community_report
SET status = 'RESOLVED', resolution = #{resolution}, moderator_id = #{moderatorId},
    moderator_note = #{moderatorNote}, version = version + 1, resolved_at = #{resolvedAt}
WHERE id = #{reportId} AND status = 'PENDING' AND version = #{expectedVersion}

mapper.select:
SELECT checkin_date FROM community_checkin
WHERE user_id = #{userId} AND checkin_date BETWEEN #{start} AND #{end}
ORDER BY checkin_date
